static BOOL gald_resp_color(NFObject *__o) {
return __o && ((struct gald_vtable *)__o->isa->vtable)->color != 0;
}

/* respondsToSelector: helper for selector member 'poke' */
static BOOL gald_resp_poke(NFObject *__o) {
return __o && ((struct gald_vtable *)__o->isa->vtable)->poke != 0;
}

